import subprocess,shlex,json,datetime
from pathlib import Path
code="""import sys,json,platform,hashlib\nfrom pathlib import Path\nr=Path('/work/ring_repo');sys.path[:0]=[str(r),str(r/'scripts')]\nimport torch,numpy\ntorch.set_num_threads(2)\nimport local_return_feedback as f\np=torch.load(r/'results/local_return_feedback_design/banks/feedback_hard.pt',map_location='cpu',weights_only=True);cfg=json.loads((r/'models/gc100/gc100_lstm_s1_1000M.json').read_text())\ns=f.TrialStreams(491801);before=s.snapshot();g=s.draw(16,f.STAGE,cfg,headings=16);after=s.snapshot()\ndef rng(v):\n return {'seed':v['seed'],'batches':v['batches'],'contexts':v['contexts'],'generators':{k:{'sha256':hashlib.sha256(t.numpy().tobytes()).hexdigest(),'bytes_hex':t.numpy().tobytes().hex()} for k,t in v['generators'].items()}}\nrows={}\nfor k in ['goal','motor','state']:\n v=p[k];z=g[k];indices=(v!=z).nonzero()[:8];rows[k]=[{'index':i.tolist(),'saved':float(v[tuple(i)]),'generated':float(z[tuple(i)])} for i in indices]\nu=torch.rand(16,19,generator=torch.Generator().manual_seed(491801))\nprint(json.dumps({'python':sys.version,'torch':str(torch.__version__),'numpy':numpy.__version__,'machine':platform.machine(),'system':platform.system(),'threads':torch.get_num_threads(),'before':rng(before),'after':rng(after),'raw_uniform_plan':{'shape':list(u.shape),'sha256':hashlib.sha256(u.numpy().tobytes()).hexdigest(),'bytes_hex':u.numpy().tobytes().hex()},'first_differences':rows,'no_policy_forward':True,'no_environment_step':True,'no_optimizer_update':True}))\n"""
name='ring-20261105-feedback-grid-reset-01'
r=subprocess.run(['gcloud','compute','ssh',name,'--project','connectome-ai-research','--zone','us-central1-a','--quiet','--command','/usr/bin/python3 -c '+shlex.quote(code)],capture_output=True,text=True,timeout=90)
out=Path('results/local_return_feedback_design/cloud_audit')
if r.returncode==0:
 data=json.loads(r.stdout.strip().splitlines()[-1]);data['worker']=name;data['utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();p=out/'bank_regeneration_private_streams.json';p.write_text(json.dumps(data,indent=2)+'\n');print(str(p))
else:print(r.returncode,r.stderr[-1000:])
